import { Table, BooleanColumn, StringColumn, GenericColumn, UrlColumn } from '../../db'

export const sys_ui_page = Table({
    allowWebServiceAccess: true,
    attributes: {
        no_table_trace: true,
        update_synch: true,
    },
    audit: true,
    extends: 'sys_metadata',
    label: 'UI Page',
    name: 'sys_ui_page',
    schema: {
        direct: BooleanColumn({
            label: [
                {
                    hint: 'Omit standard HTML header and JavaScript',
                    label: 'Direct',
                    plural: 'Directs',
                },
            ],
        }),
        description: StringColumn({
            attributes: {
                edge_encryption_enabled: true,
            },
            label: 'Description',
            maxLength: 4000,
        }),
        processing_script: GenericColumn({
            columnType: 'script_plain',
            label: 'Processing script',
            maxLength: 8000,
        }),
        client_script: GenericColumn({
            attributes: {
                client_script: true,
            },
            script: 'true',
            columnType: 'script_plain',
            label: 'Client script',
            maxLength: 8000,
        }),
        html: GenericColumn({
            columnType: 'xml',
            default: `<?xml version="1.0" encoding="utf-8" ?>\r
<j:jelly trim="false" xmlns:j="jelly:core" xmlns:g="glide" xmlns:j2="null" xmlns:g2="null">\r
\r
</j:jelly>`,
            label: [
                {
                    hint: 'Must be in XML format',
                    label: 'HTML',
                    plural: 'HTMLs',
                },
            ],
            maxLength: 65000,
            xmlView: true,
        }),
        endpoint: UrlColumn({
            attributes: {
                url_click_save: true,
            },
            dynamicValueDefinitions: {
                type: 'calculated_value',
                calculatedValue: `var scope = (current.sys_scope.scope+'').toLowerCase();
if (scope && scope != 'global')
    current.display_name = current.sys_scope.scope + '_' + current.name + '.do';`,
            },
            label: [
                {
                    hint: 'URL for the Application-scoped UI page',
                    label: 'Endpoint',
                    plural: 'Endpoints',
                },
            ],
            maxLength: 200,
            readOnly: true,
            readOnlyOption: 'client_script_modifiable',
        }),
        category: StringColumn({
            attributes: {
                edge_encryption_enabled: true,
            },
            default: 'general',
            choices: {
                catalog: {
                    label: 'Service Catalog',
                },
                cms: {
                    label: 'Content Management',
                },
                general: {
                    label: 'General',
                },
                homepages: {
                    label: 'Home Pages',
                },
                htmleditor: {
                    label: 'HTML Editor',
                },
                kb: {
                    label: 'Knowledge Base',
                },
            },
            dropdown: 'dropdown_with_none',
            label: 'Category',
        }),
        sys_id: GenericColumn({
            mandatory: false,
            label: 'Sys ID',
            read_only: false,
            active: true,
            column_type: 'GUID',
        }),
        name: StringColumn({
            attributes: {
                edge_encryption_enabled: true,
            },
            label: [
                {
                    hint: 'used in URL generation, e.g. name.do, but without the .do!',
                    label: 'Name',
                    plural: 'Names',
                },
            ],
            maxLength: 250,
        }),
    },
    textIndex: true,
})
